// deepdiff.mjs — pure-Node ESM port of the subset of deepdiff.DeepDiff
// exercised by the original Python script. Self-contained: no imports.
//
// deepDiff(t1, t2) returns a plain JS value mirroring DeepDiff's result
// dict so that pyRepr(deepDiff(a, b)) reproduces the Python printed output
// byte-for-byte. Equal inputs -> {}.

const CATEGORY_ORDER = [
  'type_changes',
  'values_changed',
  'dictionary_item_added',
  'dictionary_item_removed',
  'iterable_item_added',
  'iterable_item_removed',
];

function pyTypeName(value) {
  if (value === null || value === undefined) return 'NoneType';
  if (Array.isArray(value)) return 'list';
  switch (typeof value) {
    case 'string':
      return 'str';
    case 'boolean':
      return 'bool';
    case 'number':
      return Number.isInteger(value) ? 'int' : 'float';
    case 'object':
      return 'dict';
    default:
      return typeof value;
  }
}

function isDict(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function addChange(acc, category, path, detail) {
  acc[category][path] = detail;
}

function diffInto(t1, t2, path, acc) {
  if (t1 === t2) return;

  const type1 = pyTypeName(t1);
  const type2 = pyTypeName(t2);
  if (type1 !== type2) {
    addChange(acc, 'type_changes', path, {
      old_type: type1,
      new_type: type2,
      old_value: t1,
      new_value: t2,
    });
    return;
  }

  if (isDict(t1)) {
    for (const key of Object.keys(t1)) {
      const childPath = `${path}['${key}']`;
      if (!hasOwn(t2, key)) {
        addChange(acc, 'dictionary_item_removed', childPath, t1[key]);
      } else {
        diffInto(t1[key], t2[key], childPath, acc);
      }
    }
    for (const key of Object.keys(t2)) {
      if (!hasOwn(t1, key)) {
        addChange(acc, 'dictionary_item_added', `${path}['${key}']`, t2[key]);
      }
    }
    return;
  }

  if (Array.isArray(t1)) {
    const common = Math.min(t1.length, t2.length);
    for (let i = 0; i < common; i++) {
      diffInto(t1[i], t2[i], `${path}[${i}]`, acc);
    }
    for (let i = common; i < t2.length; i++) {
      addChange(acc, 'iterable_item_added', `${path}[${i}]`, t2[i]);
    }
    for (let i = common; i < t1.length; i++) {
      addChange(acc, 'iterable_item_removed', `${path}[${i}]`, t1[i]);
    }
    return;
  }

  // Primitive leaf with the same Python type but a different value.
  addChange(acc, 'values_changed', path, { new_value: t2, old_value: t1 });
}

export function deepDiff(t1, t2, path = 'root') {
  const acc = {};
  for (const category of CATEGORY_ORDER) acc[category] = {};

  diffInto(t1, t2, path, acc);

  const result = {};
  for (const category of CATEGORY_ORDER) {
    if (Object.keys(acc[category]).length > 0) result[category] = acc[category];
  }
  return result;
}

