// Python's difflib.unified_diff generator yields them; the caller joins
// them with '\n'.

// Python str.splitlines(): splits on \n, \r, \r\n, \v, \f, \x1c, \x1d,
// \x1e, \x85,   and  . A trailing line boundary does not produce a
// trailing empty element.
export function splitLines(s) {
  const lines = [];
  const n = s.length;
  let start = 0;
  let i = 0;
  while (i < n) {
    const c = s.charCodeAt(i);
    let boundary = 0;
    if (c === 0x0d) {
      // \r or \r\n
      boundary = i + 1 < n && s.charCodeAt(i + 1) === 0x0a ? 2 : 1;
    } else if (
      c === 0x0a || c === 0x0b || c === 0x0c ||
      c === 0x1c || c === 0x1d || c === 0x1e || c === 0x85 ||
      c === 0x2028 || c === 0x2029
    ) {
      boundary = 1;
    }
    if (boundary) {
      lines.push(s.slice(start, i));
      i += boundary;
      start = i;
    } else {
      i++;
    }
  }
  if (start < n) lines.push(s.slice(start));
  return lines;
}

// Port of difflib.SequenceMatcher. We never pass an isjunk function, so
// bjunk stays empty; it is kept (as an empty Set) for faithfulness.
class SequenceMatcher {
  constructor(a, b, autojunk = true) {
    this.isjunk = null;
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this.matchingBlocks = null;
    this.opcodes = null;
    this.chainB();
  }

  chainB() {
    const b = this.b;
    const b2j = new Map();
    for (let i = 0; i < b.length; i++) {
      const elt = b[i];
      let indices = b2j.get(elt);
      if (indices === undefined) {
        indices = [];
        b2j.set(elt, indices);
      }
      indices.push(i);
    }
    // Purge junk elements (isjunk is always null here, so none).
    this.bjunk = new Set();
    // Purge popular elements that are not junk.
    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [elt, idxs] of b2j) {
        if (idxs.length > ntest) {
          this.bpopular.add(elt);
          b2j.delete(elt);
        }
      }
    }
    this.b2j = b2j;
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b, b2j, bjunk } = this;
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;
    let j2len = new Map();
    const nothing = [];
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map();
      const indices = b2j.get(a[i]) ?? nothing;
      for (const j of indices) {
        if (j < blo) continue;
        if (j >= bhi) break;
        const k = (j2len.get(j - 1) ?? 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }
    // Extend the best match with non-junk on each side (bjunk is empty,
    // so this is plain equality extension, exactly as CPython does).
    while (
      besti > alo && bestj > blo &&
      !bjunk.has(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti--; bestj--; bestsize++;
    }
    while (
      besti + bestsize < ahi && bestj + bestsize < bhi &&
      !bjunk.has(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize++;
    }
    // Junk extension (never triggers with bjunk empty; kept for parity).
    while (
      besti > alo && bestj > blo &&
      bjunk.has(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti--; bestj--; bestsize++;
    }
    while (
      besti + bestsize < ahi && bestj + bestsize < bhi &&
      bjunk.has(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize++;
    }
    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocks !== null) return this.matchingBlocks;
    const la = this.a.length;
    const lb = this.b.length;
    // LIFO queue, exactly like CPython's list.pop().
    const queue = [[0, la, 0, lb]];
    const matchingBlocks = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const [i, j, k] = this.findLongestMatch(alo, ahi, blo, bhi);
      if (k) {
        matchingBlocks.push([i, j, k]);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }
    matchingBlocks.sort((x, y) => x[0] - y[0] || x[1] - y[1] || x[2] - y[2]);
    let i1 = 0, j1 = 0, k1 = 0;
    const nonAdjacent = [];
    for (const [i2, j2, k2] of matchingBlocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
        k1 += k2;
      } else {
        if (k1) nonAdjacent.push([i1, j1, k1]);
        i1 = i2; j1 = j2; k1 = k2;
      }
    }
    if (k1) nonAdjacent.push([i1, j1, k1]);
    nonAdjacent.push([la, lb, 0]);
    this.matchingBlocks = nonAdjacent;
    return nonAdjacent;
  }

  getOpcodes() {
    if (this.opcodes !== null) return this.opcodes;
    let i = 0, j = 0;
    const answer = [];
    for (const [ai, bj, size] of this.getMatchingBlocks()) {
      let tag = '';
      if (i < ai && j < bj) tag = 'replace';
      else if (i < ai) tag = 'delete';
      else if (j < bj) tag = 'insert';
      if (tag) answer.push([tag, i, ai, j, bj]);
      i = ai + size;
      j = bj + size;
      if (size) answer.push(['equal', ai, i, bj, j]);
    }
    this.opcodes = answer;
    return answer;
  }

  *getGroupedOpcodes(n = 3) {
    let codes = this.getOpcodes();
    if (codes.length === 0) codes = [['equal', 0, 1, 0, 1]];
    if (codes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[0];
      codes[0] = [tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2];
    }
    if (codes[codes.length - 1][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[codes.length - 1];
      codes[codes.length - 1] = [tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)];
    }
    const nn = n + n;
    let group = [];
    for (const [tag, i1, i2, j1, j2] of codes) {
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        yield group;
        group = [[tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2]];
        continue;
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length > 0 && !(group.length === 1 && group[0][0] === 'equal')) {
      yield group;
    }
  }
}

// Port of difflib._format_range_unified.
function formatRangeUnified(start, stop) {
  let beginning = start + 1;
  const length = stop - start;
  if (length === 1) return `${beginning}`;
  if (length === 0) beginning -= 1;
  return `${beginning},${length}`;
}

// Port of difflib.unified_diff(a, b, fromfile='', tofile='',
// fromfiledate='', tofiledate='', n=3, lineterm='') returning the yielded
// lines as an array (caller joins with '\n').
export function unifiedDiff(aLines, bLines, n = 3) {
  const result = [];
  let started = false;
  const matcher = new SequenceMatcher(aLines, bLines);
  for (const group of matcher.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      result.push('--- ');
      result.push('+++ ');
    }
    const first = group[0];
    const last = group[group.length - 1];
    const file1Range = formatRangeUnified(first[1], last[2]);
    const file2Range = formatRangeUnified(first[3], last[4]);
    result.push(`@@ -${file1Range} +${file2Range} @@`);
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) result.push(' ' + aLines[i]);
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (let i = i1; i < i2; i++) result.push('-' + aLines[i]);
      }
      if (tag === 'replace' || tag === 'insert') {
        for (let j = j1; j < j2; j++) result.push('+' + bLines[j]);
      }
    }
  }
  return result;
}

